SET NAMES utf8mb4;
SET time_zone = '+08:00';
START TRANSACTION;
SET @brewery_jiale = (SELECT brewery_id FROM portal_account WHERE phone = CONVERT(0x3133393738383536363633 USING utf8mb4) LIMIT 1);
UPDATE beer_entry e JOIN entry_scan_label l ON l.beer_entry_id=e.id SET e.brewery_id=@brewery_jiale WHERE e.competition_id=1070 AND l.competition_id=1070 AND l.short_code IN ('08918','13027');
